<?php

declare(strict_types=1);

namespace App\Storage;

/**
 * Object keys: generated by the server, never taken from an uploaded file name. A key is one or
 * more segments of letters, digits, ".", "_" and "-", separated by "/", up to 255 characters, with
 * no empty, "." or ".." segment and no segment starting with "." (so no hidden files and no way to
 * reach outside the storage).
 */
final class StorageKey
{
    public const MAX_LENGTH = 255;

    public static function isValid(string $key): bool
    {
        if ($key === '' || strlen($key) > self::MAX_LENGTH) {
            return false;
        }
        foreach (explode('/', $key) as $segment) {
            if ($segment === '' || $segment[0] === '.' || !preg_match('/^[A-Za-z0-9._-]+$/', $segment)) {
                return false;
            }
        }
        return true;
    }

    /** @throws StorageError for an unsafe key */
    public static function assertValid(string $key): void
    {
        if (!self::isValid($key)) {
            throw new StorageError('Invalid storage key.');
        }
    }

    /** A new key for an uploaded picture: prod_<date>_<time>_<random>.<extension>. */
    public static function forUpload(string $extension): string
    {
        $extension = strtolower(preg_replace('/[^a-z0-9]/i', '', $extension) ?? '');
        return 'prod_' . date('Ymd_His') . '_' . bin2hex(random_bytes(4)) . '.' . ($extension !== '' ? $extension : 'bin');
    }

    /** The key in a stored public path ("/uploads/<key>" or a full URL containing it), or null. */
    public static function fromPublicPath(string $value): ?string
    {
        if (!preg_match('#/uploads/([A-Za-z0-9._/-]+)#', $value, $m)) {
            return null;
        }
        return self::isValid($m[1]) ? $m[1] : null;
    }

    /** Cache-Control for a key: admin uploads never change (unique names); others for a day. */
    public static function cacheControl(string $key): string
    {
        return preg_match('/^prod_\d{8}_\d{6}_[0-9a-f]{8}\.(jpe?g|png|webp)$/', $key)
            ? 'public, max-age=31536000, immutable'
            : 'public, max-age=86400';
    }
}
